/// MAP_ORDER — 지도 렌더 순서(프로토타입과 동일하게 유지).
List<Region> get kRegionsInMapOrder => kRegions;

/// id에 해당하는 지역을 찾는다. 잘못되거나 오래된 링크로 알 수 없는 id가 들어올 수 있어
/// (예: `/region/:id` 진입) 예외를 던지는 대신 null을 반환한다(CodeRabbit 리뷰 반영).
Region? regionById(String id) {
  for (final region in kRegions) {
    if (region.id == id) return region;
  }
  return null;
}

/// 백엔드 카탈로그의 지역 stable key를 앱의 정적 지역으로 해석한다.
/// 서버 key가 앱 카탈로그에 없으면 `null`을 반환하며, 호출자가 화면별 오류·대체 정책을 결정한다.
Region? regionByStableKey(String stableKey) => regionById(stableKey);

/// 백엔드 region_name(예: "청주시") → 로컬 지역 id(예: 'cheongju') 매칭
/// ([020-frontend-map-sync] 참고). 못 찾으면 null(백엔드에만 있는 지역은 조용히 무시).
String? regionIdByName(String name) {
  for (final region in kRegions) {
    if (region.name == name) return region.id;
  }
  return null;
}

/// "단양군" → "단양 여행" — 여행 목록 카드 제목([Figma] 여행 목록 화면).
String tripTitleFor(Region region) {
  final shortName = region.name.replaceAll(RegExp(r'(광역시|특별시|시|군)$'), '');
  return '$shortName 여행';
}
